#include <iostream>
#include <vector>
#include <string>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> par(n);
    for (int i = 0; i < n; i++) cin >> par[i];
    long long q;
    cin >> q;
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    const int LOG = 15;
    int count = (int)n;
    vector<vector<int>> kids(count + 1);
    int root = 0;
    for (int v = 1; v <= count; v++) {
        if (par[v - 1] == 0) root = v;
        else kids[par[v - 1]].push_back(v);
    }
    vector<int> depth(count + 1, 0), order = {root};
    for (size_t i = 0; i < order.size(); i++) {
        for (int c : kids[order[i]]) {
            depth[c] = depth[order[i]] + 1;
            order.push_back(c);
        }
    }
    vector<vector<int>> up(LOG, vector<int>(count + 1, 0));
    for (int v = 1; v <= count; v++) up[0][v] = (int)par[v - 1];
    for (int j = 1; j < LOG; j++) {
        for (int v = 1; v <= count; v++) up[j][v] = up[j - 1][up[j - 1][v]];
    }
    for (const vector<long long>& query : qs) {
        int u = (int)query[0], v = (int)query[1];
        if (depth[u] < depth[v]) swap(u, v);
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; j++) {
            if ((diff >> j) & 1) u = up[j][u];
        }
        if (u == v) {
            cout << u << "\n";
            continue;
        }
        for (int j = LOG - 1; j >= 0; j--) {
            if (up[j][u] != up[j][v]) {
                u = up[j][u];
                v = up[j][v];
            }
        }
        cout << up[0][u] << "\n";
    }

    return 0;
}

