import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] par = new long[(int) n];
        for (int i = 0; i < par.length; i++) par[i] = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int LOG = 15;
        int count = (int) n;
        List<List<Integer>> kids = new ArrayList<>();
        for (int v = 0; v <= count; v++) kids.add(new ArrayList<>());
        int root = 0;
        for (int v = 1; v <= count; v++) {
            if (par[v - 1] == 0) root = v;
            else kids.get((int) par[v - 1]).add(v);
        }
        int[] depth = new int[count + 1];
        List<Integer> order = new ArrayList<>();
        order.add(root);
        for (int i = 0; i < order.size(); i++) {
            int v = order.get(i);
            for (int c : kids.get(v)) {
                depth[c] = depth[v] + 1;
                order.add(c);
            }
        }
        int[][] up = new int[LOG][count + 1];
        for (int v = 1; v <= count; v++) up[0][v] = (int) par[v - 1];
        for (int j = 1; j < LOG; j++) {
            for (int v = 1; v <= count; v++) up[j][v] = up[j - 1][up[j - 1][v]];
        }
        StringBuilder out = new StringBuilder();
        for (long[] query : qs) {
            int u = (int) query[0], v = (int) query[1];
            if (depth[u] < depth[v]) {
                int t = u;
                u = v;
                v = t;
            }
            int diff = depth[u] - depth[v];
            for (int j = 0; j < LOG; j++) {
                if (((diff >> j) & 1) != 0) u = up[j][u];
            }
            if (u == v) {
                out.append(u).append("\n");
                continue;
            }
            for (int j = LOG - 1; j >= 0; j--) {
                if (up[j][u] != up[j][v]) {
                    u = up[j][u];
                    v = up[j][v];
                }
            }
            out.append(up[0][u]).append("\n");
        }
        System.out.print(out);
    }
}
